"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Coral Triangle Run', 'author': 'Signature original', 'genre': 'Lost Treasures', 'chapters': [{'n': 1, 'title': 'The Call of the Wild', 'text': "By dawn they were over the Coral Triangle, the green unrolling below like a held breath. Jack Hart checked a pharaoh's seal one more time. It hummed faintly, the way true things do when they're near their home.\n\nJack Hart was fixing an engine when a pharaoh's seal arrived — by courier, no return address, with a note: 'You know what this is. Come to the Coral Triangle. Hurry.' Jack Hart knew. Everyone in their line knew the legend.\n\nThe landing was rough — it always is — and the Coral Triangle swallowed them whole: heat, noise, green. the engineer Marco grinned. 'Just like old times.' Jack Hart grinned back. Old times had nearly killed them twice."}, {'n': 2, 'title': 'Into the Green', 'text': "The ruins nearly ended it: rapids, a broken rope, Jack Hart in the water with a pharaoh's seal in a waterproof bag and the engineer Marco's hand the only solid thing in the world. 'Never leave a friend behind,' the engineer Marco gasped. 'Your rule.'\n\nJack Hart laughed, coughed river, and lived. That night they found the first marker — an ancient carving that matched a pharaoh's seal exactly. The legend was real. It had always been real.\n\nThey were followed now; the engineer Marco spotted the glint of scopes at dusk. the rival expedition wasn't just ahead — the rival expedition was around. Jack Hart doubled the watch and slept with a pharaoh's seal under their head."}, {'n': 3, 'title': 'The Ruins', 'text': "They emerged into daylight as the gate sealed forever behind the rival expedition's screams — no, wait. Jack Hart went back. Because the real treasure is the journey, and because no one gets left, not even the bad guys. They dragged the rival expedition out by the collar.\n\nInside: wonders. the engineer Marco, the scholar at heart, wept at the murals. Jack Hart kept watch, because wonders in such places usually have teeth. They did: the floor was a trap, the walls were a trap, the air was a trap.\n\nThe ruins of the Coral Triangle were a puzzle built by people who didn't want visitors. a pharaoh's seal was the key — literally; it fit a slot in the great door, and the stone sighed open after a thousand years."}, {'n': 4, 'title': 'The Price of Gold', 'text': "the rival expedition, bound and furious, offered everything: money, power, a share. Jack Hart listened politely and said no politely, which infuriated the rival expedition more than any insult. Some people can't be bought. Some treasures can't be sold.\n\nThe trek out was worse than the trek in: the rival expedition's backup team, the river rising, the engineer Marco feverish from a scratch that turned ugly. Jack Hart carried the engineer Marco and a pharaoh's seal in turns, and learned what shoulders are for.\n\nAt the riddle, they made their stand: outnumbered, outgunned, but holding the high ground and the moral ground, which as the engineer Marco said weakly, 'is worth at least two guns.'"}, {'n': 5, 'title': 'The Real Treasure', 'text': "the real treasure is the journey — Jack Hart wrote it in the expedition log, under the date, under the coordinates of the Coral Triangle. Then closed the book. Then opened the new map.\n\nA kid asked Jack Hart if it was worth it — the danger, the lost years. Jack Hart thought of the river, the ruins, the engineer Marco's hand in the rapids. 'The thing,' Jack Hart said, 'was never the thing.'\n\nThe museum opening was black tie. Jack Hart wore boots. the engineer Marco, recovered and insufferable, wore a grin. a pharaoh's seal sat behind glass, humming faintly, home at last among people who'd care for it."}, {'n': 6, 'title': 'Next Horizon', 'text': "Engines up. the real treasure is the journey. The horizon, as always, was just the beginning.\n\nThe plane — or boat, or truck, or camel — was already arranged. It always is, when a pharaoh's seal calls. That's the thing about legends: they don't end. They just wait for the next believer.\n\nthe engineer Marco was packed before Jack Hart finished reading the note. 'Where to?' the engineer Marco asked. Jack Hart pointed at the map's edge, past the Coral Triangle, past everything known. 'There,' Jack Hart said."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

